hl.on("hyprland.start", function()
    hl.exec_cmd("waypaper --restore")
    -- theme.sh must run BEFORE waybar: style.css @imports /tmp/waybar-colors.css,
    -- which is wiped on reboot (tmpfs) and regenerated by this script.
    -- Starting waybar without it makes waybar exit with a CSS import error.
    hl.exec_cmd("~/.config/waybar/theme.sh && waybar")
    -- Bottom auto-hide dock: disabled for now, code kept in scripts/popup-dock.sh.
    -- Re-enable by uncommenting the line below.
    -- hl.exec_cmd("~/.config/hypr/scripts/popup-dock.sh &")
    hl.exec_cmd("nm-applet --indicator")
    hl.exec_cmd("swaync")
    -- Volume/brightness popups for the media keys
    hl.exec_cmd("swayosd-server")
    hl.exec_cmd("hypridle")
    -- Password prompts for apps that need admin rights (pkexec, Thunar mounts, ...)
    hl.exec_cmd("systemctl --user start hyprpolkitagent")
    -- Disables blur/shadows/animations on battery, restores them on AC.
    hl.exec_cmd("~/.config/hypr/scripts/battery-mode.sh")
    -- Keeps the screen awake while media plays (hypridle honours it).
    hl.exec_cmd("~/.config/hypr/scripts/media-inhibit.sh")
end)
